<style>
:root{--paper:#faf7f2;--panel:#fffdf9;--ink:#35252a;--muted:#7e6b67;--wine:#641b2a;--gold:#b78a54;--line:#ddcfc1;--soft:#f4ebe1;color-scheme:light}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:'DM Sans',sans-serif;padding:40px 24px max(26px,env(safe-area-inset-bottom));min-height:100svh}main{max-width:940px;margin:auto}a{color:var(--wine);text-decoration:none}a:focus-visible,button:focus-visible{outline:2px solid var(--gold);outline-offset:4px}.brand{display:block;width:max-content;margin:0 auto 32px;text-align:center;line-height:1.2}.brand>span{font-family:'Playfair Display',Georgia,serif;font-size:25px;letter-spacing:.18em}.brand small{display:block;font-size:8px;letter-spacing:.25em;margin-top:5px}.attendance-shell{display:grid;grid-template-columns:1fr 1.1fr;background:var(--panel);border:1px solid var(--line);border-radius:9px;overflow:hidden;box-shadow:0 16px 60px #3b202808}.event-header{position:relative;isolation:isolate;overflow:hidden;background:linear-gradient(135deg,#301019ed,#641b2ae8),url('/images/swe-home-hero.jpg') 70% center/cover;color:#fff4ec;padding:52px 35px;display:flex;flex-direction:column;align-items:flex-start;min-width:0}.event-header:after{content:'';width:230px;height:270px;border:1px solid #edcda92a;border-radius:48%;position:absolute;right:-110px;bottom:-100px;z-index:-1;transform:rotate(-22deg)}.eyebrow{font-size:8px;font-weight:600;letter-spacing:.2em;color:#e6c7a2}h1,h2{font-family:'Playfair Display',Georgia,serif;font-weight:400;letter-spacing:-.035em}h1{font-size:39px;line-height:1.15;margin:24px 0;overflow-wrap:anywhere}p{line-height:1.85;margin:0}.event-date{font-size:12px;color:#f0d9cf}.event-location{font-size:11px;color:#dec2b7;margin-top:12px}.event-tag{display:inline-flex;align-items:center;gap:8px;margin-top:auto;padding-top:40px;font-size:8px;letter-spacing:.12em;color:#e6c7a2}.event-tag>span{width:5px;height:5px;background:#d4ad7f;border-radius:50%}.attendance-content{padding:44px 34px;min-width:0}.section-kicker{display:flex;align-items:center;gap:10px;font-size:8px;font-weight:600;letter-spacing:.17em;color:var(--muted)}.line{width:24px;height:1px;background:var(--gold)}h2{font-size:31px;line-height:1.2;margin:18px 0 14px}.intro{font-size:12px;color:var(--muted)}.visitor-welcome{margin-bottom:18px}.hours{display:flex;align-items:center;gap:9px;font-size:10px;color:var(--muted);padding:13px 0 20px}.hours svg,.notice svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.5;flex-shrink:0}.field{margin-bottom:18px}label{display:block;font-size:11px;font-weight:500;margin-bottom:7px}input{width:100%;min-width:0;border:1px solid #cdb9a8;background:var(--panel);color:var(--ink);border-radius:4px;font:inherit;font-size:16px;padding:12px 13px;min-height:46px}input::placeholder{color:#a28f85;font-size:12px}input:focus{outline:2px solid var(--gold);outline-offset:2px}input[aria-invalid=true],select[aria-invalid=true]{border-color:#a34847}select{width:100%;min-width:0;border:1px solid #cdb9a8;background:var(--panel);color:var(--ink);border-radius:4px;font:inherit;font-size:16px;padding:12px 13px;min-height:46px}select:focus{outline:2px solid var(--gold);outline-offset:2px}.field[hidden]{display:none}.error{font-size:11px;color:#a34847;margin-top:6px}button{width:100%;display:flex;align-items:center;justify-content:space-between;border:1px solid var(--wine);border-radius:4px;background:var(--wine);color:#fff;padding:14px 17px;font:inherit;font-size:12px;font-weight:500;cursor:pointer;min-height:47px;transition:background .2s}button:hover{background:#4d1421}button>span{font-size:19px}.notice{display:flex;gap:15px;background:var(--soft);border:1px solid var(--line);border-left:3px solid var(--gold);border-radius:5px;padding:21px 18px;margin:24px 0 16px}.notice-icon{color:var(--wine);padding-top:2px}.notice h3{font-size:12px;font-weight:600;margin:0 0 8px;color:var(--wine)}.notice p{font-size:13px}.note{font-size:11px;color:var(--muted)}.success-modal{width:min(420px,calc(100vw - 32px));max-width:100%;max-height:calc(100svh - 32px - env(safe-area-inset-top) - env(safe-area-inset-bottom));margin:auto;padding:0;border:1px solid var(--line);border-radius:9px;background:var(--panel);color:var(--ink);box-shadow:0 16px 60px #3b202840;overflow:auto}.success-modal::backdrop{background:#1d121680}.success-card{padding:32px 22px max(22px,env(safe-area-inset-bottom));text-align:center;min-width:0}.success-modal .eyebrow{color:var(--wine)}.success-modal h2{font-size:30px;line-height:1.2;margin:14px 0 8px;overflow-wrap:anywhere}.success-modal p{font-size:14px;color:var(--muted);overflow-wrap:anywhere}.success-modal button{margin-top:22px}.content-footer{display:flex;flex-wrap:wrap;gap:15px;justify-content:space-between;align-items:center;border-top:1px solid var(--line);padding-top:22px;margin-top:30px}.content-footer>span{font-size:7px;letter-spacing:.14em;color:var(--muted)}.content-footer a{font-size:10px}footer{text-align:center;color:var(--muted);font-size:10px;padding-top:25px;line-height:1.9}footer a{display:block;font-size:9px;margin-top:7px}
html[data-color-theme=dark]{--paper:#1d1719;--panel:#2b2226;--ink:#efdfd6;--muted:#c4afa6;--wine:#e8bf8f;--line:#514047;--soft:#36292f;color-scheme:dark}html[data-color-theme=dark] button{background:#641b2a;border-color:#9a5263}html[data-color-theme=dark] button:hover{background:#782d3d}
html[data-color-theme=dark] .error{color:#e2aaa0}html[data-color-theme=dark] input[aria-invalid=true]{border-color:#bd8581}
.visitor-prizes{margin:23px 0;padding:21px 18px;background:var(--soft);border:1px solid var(--line);border-radius:5px}.visitor-prizes>.eyebrow{color:var(--wine);font-size:7px}.visitor-prizes h3{font-family:'Playfair Display',Georgia,serif;color:var(--ink);font-size:23px;line-height:1.3;font-weight:400;letter-spacing:-.02em;margin:12px 0}.visitor-prizes>p{font-size:11px;color:var(--muted)}.visitor-prizes ul{list-style:none;padding:0;margin:17px 0 0}.visitor-prizes li{display:flex;align-items:flex-start;gap:10px;padding:13px 0;border-top:1px solid var(--line);font-size:12px}.prize-mark{color:var(--gold);padding-top:1px}.visitor-prizes li>div{flex:1;min-width:0;overflow-wrap:anywhere}.visitor-prizes li strong{font-weight:600}.visitor-prizes li p{font-size:10px;color:var(--muted);margin-top:5px}.prize-quantity{color:var(--wine);font-size:9px;white-space:nowrap;padding-top:2px}.prize-terms{border-top:1px solid var(--line);padding-top:14px;margin-top:4px;font-size:10px}.prize-terms strong{color:var(--wine);font-weight:500}.prize-terms p{margin-top:6px;white-space:pre-line;overflow-wrap:anywhere;color:var(--muted)}
@media(max-width:640px){body{padding:26px 18px max(26px,env(safe-area-inset-bottom))}.brand{margin-bottom:24px}.attendance-shell{grid-template-columns:1fr}.event-header{padding:30px 25px}.eyebrow{font-size:7px}h1{font-size:33px;margin:18px 0 16px}.event-tag{padding-top:24px}.event-location{margin-top:8px}.attendance-content{padding:29px 24px 25px}h2{font-size:29px}.notice{padding:18px 15px}.content-footer{margin-top:26px}}
@media(prefers-reduced-motion:reduce){button{transition:none}}
</style>
